package ais.common.newui.lkp;
import java.util.Calendar;import java.util.List;import java.util.Set;import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpServletResponse;import org.json.JSONArray;import org.json.JSONObject;import ais.action.master.sekolah.util.SekolahUtil;import ais.common.Common;import ais.common.newui.NewUiRouteGuard;import ais.common.newui.lkp.NewUiWorkRealizationService.Detail;import ais.common.newui.lkp.NewUiWorkRealizationService.Filter;import ais.common.newui.lkp.NewUiWorkRealizationService.Option;import ais.common.newui.lkp.NewUiWorkRealizationService.Row;import ais.common.newui.lkp.NewUiWorkRealizationService.Snapshot;import ais.database.model.Tbmuser;import ais.database.model.lkp.KegiatanTugasJabatan;import ais.database.model.rab.SatuanKerja;
/** Endpoint native realisasi dan verifikasi kerja pegawai. */
public final class NewUiWorkRealizationController{private NewUiWorkRealizationController(){}public static void handle(HttpServletRequest q,HttpServletResponse r)throws Exception{r.setContentType("application/json; charset=UTF-8");r.setHeader("Cache-Control","no-store");JSONObject j=new JSONObject();try{String action=text(q.getParameter("action"),"list"),priv="verify".equals(action)?"update":"list";if(!NewUiRouteGuard.isActionAuthorized(q,"lkp","realisasi_kerja_pegawai",priv)){r.setStatus(403);fail(j,"ACTION_FORBIDDEN","Hak akses tidak tersedia.");write(r,j);return;}Set<SatuanKerja>units=SekolahUtil.ambilSatuanKerjas();Tbmuser user=Common.getCurrentUser(q);NewUiWorkRealizationService s=new NewUiWorkRealizationService();if("list".equals(action)){Calendar now=Calendar.getInstance();Filter f=new Filter();f.query=q.getParameter("q");f.period=text(q.getParameter("period"),KegiatanTugasJabatan.BULANAN);f.year=integer(q.getParameter("year"),now.get(Calendar.YEAR));f.month=clean(q.getParameter("month"))==null?Integer.valueOf(now.get(Calendar.MONTH)):Integer.valueOf(integer(q.getParameter("month"),now.get(Calendar.MONTH)));f.employeeId=id(q.getParameter("employeeId"));f.unitId=id(q.getParameter("unitId"));f.page=Math.max(0,integer(q.getParameter("page"),0));f.size=Math.min(100,Math.max(10,integer(q.getParameter("size"),20)));encode(j,s.load(f,units,user));j.put("csrfHeader","X-CSRF-Token").put("csrfToken",csrfToken(q));}else if("details".equals(action))j.put("details",details(s.details(requiredId(q.getParameter("id")),units,user)));else if("verify".equals(action)){csrf(q);s.verify(requiredId(q.getParameter("id")),Double.valueOf(decimal(q.getParameter("quality"))),bool(q.getParameter("verified")),q.getParameter("note"),units,user);}else throw new IllegalArgumentException("Aksi tidak dikenal.");j.put("ok",true);}catch(SecurityException e){r.setStatus(403);fail(j,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){r.setStatus(422);fail(j,"VALIDATION_FAILED",e.getMessage());}catch(Exception e){r.setStatus(500);fail(j,"INTERNAL_ERROR","Gagal memproses realisasi kerja pegawai.");try{ais.common.ErrorAuditUtil.record(e,"NewUiWorkRealizationController");}catch(Exception ignored){}}write(r,j);}
private static void encode(JSONObject j,Snapshot s)throws Exception{JSONArray rows=new JSONArray();for(Row x:s.rows)rows.put(new JSONObject().put("id",x.id).put("employeeId",x.employeeId).put("employee",x.employee).put("activity",x.activity).put("activityNote",x.activityNote).put("unitId",x.unitId).put("unit",x.unit).put("year",x.year).put("month",x.month).put("quantity",x.quantity).put("quality",x.quality).put("time",x.time).put("cost",x.cost).put("realizedQuantity",x.realizedQuantity).put("realizedQuality",x.realizedQuality).put("realizedTime",x.realizedTime).put("quantityUnit",x.quantityUnit).put("timeUnit",x.timeUnit).put("detailCount",x.detailCount).put("verified",x.verified).put("canAssess",x.canAssess).put("note",x.note));j.put("rows",rows).put("total",s.total).put("employees",options(s.employees)).put("units",options(s.units));}private static JSONArray options(List<Option>v)throws Exception{JSONArray a=new JSONArray();for(Option x:v)a.put(new JSONObject().put("id",x.id).put("label",x.label));return a;}private static JSONArray details(List<Detail>v)throws Exception{JSONArray a=new JSONArray();for(Detail x:v)a.put(new JSONObject().put("id",x.id).put("description",x.description).put("note",x.note).put("by",x.by).put("quantity",x.quantity).put("time",x.time).put("cost",x.cost).put("verified",x.verified).put("from",x.from).put("to",x.to));return a;}
/** Terbitkan token CSRF pada aksi baca; tanpa ini verify selalu 403 sebab tidak ada aksi lain di controller ini yang pernah mencetak newUiCsrfToken. */
private static String csrfToken(HttpServletRequest q){String t=ais.common.newui.NewUiCsrfUtil.getToken(q.getSession(true));if(q.getSession().getAttribute("newUiCsrfToken")==null)q.getSession().setAttribute("newUiCsrfToken",t);return String.valueOf(q.getSession().getAttribute("newUiCsrfToken"));}
private static void csrf(HttpServletRequest q){if(!"POST".equalsIgnoreCase(q.getMethod()))throw new SecurityException("Metode HTTP tidak valid.");Object e=q.getSession().getAttribute("newUiCsrfToken");String v=q.getHeader("X-CSRF-Token");if(e==null||v==null||!String.valueOf(e).equals(v))throw new SecurityException("Token CSRF tidak valid.");}private static Long requiredId(String v){Long x=id(v);if(x==null)throw new IllegalArgumentException("ID wajib diisi.");return x;}private static Long id(String v){if(clean(v)==null)return null;try{return Long.valueOf(v);}catch(Exception e){throw new IllegalArgumentException("ID tidak valid.");}}private static int integer(String v,int d){try{return Integer.parseInt(v);}catch(Exception e){return d;}}private static double decimal(String v){try{return Double.parseDouble(v);}catch(Exception e){throw new IllegalArgumentException("Nilai kualitas tidak valid.");}}private static boolean bool(String v){return"true".equalsIgnoreCase(v);}private static String clean(String v){return v==null||v.trim().length()==0?null:v.trim();}private static String text(String v,String d){return clean(v)==null?d:v.trim();}private static void fail(JSONObject j,String c,String m)throws Exception{j.put("ok",false).put("code",c).put("message",m);}private static void write(HttpServletResponse r,JSONObject j)throws Exception{r.getWriter().write(j.toString());}}
